-- ====================================================================
-- GAADHE KOSHA (ಗಾದೆ ಕೋಶ) - PROVERB SEED BATCH 4
-- Records: 1501 to 2000 of 2868
-- ====================================================================

INSERT INTO public.proverbs (
    kannada, transliteration, english_meaning, kannada_meaning,
    category, category_kn, situation, situation_kn, tags, contributor, likes, is_verified
) VALUES
    ('ಬಸವನ ಹಿಂದೆ ಬಾಲ, ಲಗ್ನದ ಹಿಂದೆ ಸಾಲ', 'Basavana himde baala, lagnada himde saala', '[Translation in progress] Traditional folk wisdom: "ಬಸವನ ಹಿಂದೆ ಬಾಲ, ಲಗ್ನದ ಹಿಂದೆ ಸಾಲ". Context: Guidance on money and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಬಸವನ ಹಿಂದೆ ಬಾಲ, ಲಗ್ನದ ಹಿಂದೆ ಸಾಲ". ಇದು ಹಣಕಾಸು ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'money', 'ಹಣಕಾಸು', 'Used in daily conversations to illustrate money principles and life lessons.', 'ಹಣಕಾಸು ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಬಸವನ","ಹಿಂದೆ","ಬಾಲ","ಲಗ್ನದ","ಸಾಲ","ಹಣಕಾಸು"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಅತಿ ಸ್ನೇಹ ಗತಿ ಕೇಡು', 'Ati sneeha gati keedu', '[Translation in progress] Traditional folk wisdom: "ಅತಿ ಸ್ನೇಹ ಗತಿ ಕೇಡು". Context: Guidance on friendship and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಅತಿ ಸ್ನೇಹ ಗತಿ ಕೇಡು". ಇದು ಸ್ನೇಹ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'friendship', 'ಸ್ನೇಹ', 'Used in daily conversations to illustrate friendship principles and life lessons.', 'ಸ್ನೇಹ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಅತಿ","ಸ್ನೇಹ","ಗತಿ","ಕೇಡು","ಸ್ನೇಹ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಊರಿಗೊಂದು ದಾರಿಯಾದ್ರೆ,ಎಡವಟ್ಟಂಗೆ ಅವನದ್ದೇ ದಾರಿ', 'Oorigomdu daariyaadre,edavattamge avanaddee daari', '[Translation in progress] Traditional folk wisdom: "ಊರಿಗೊಂದು ದಾರಿಯಾದ್ರೆ,ಎಡವಟ್ಟಂಗೆ ಅವನದ್ದೇ ದಾರಿ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಊರಿಗೊಂದು ದಾರಿಯಾದ್ರೆ,ಎಡವಟ್ಟಂಗೆ ಅವನದ್ದೇ ದಾರಿ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಊರಿಗೊಂದು","ದಾರಿಯಾದ್ರೆಎಡವಟ್ಟಂಗೆ","ಅವನದ್ದೇ","ದಾರಿ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಪಾಪಿ ಸಮುದ್ರ ಹೊಕ್ಕರು ಮೊಣಕಾಲುದ್ದ ನೀರು', 'Paapi samudra hokkaru monakaaludda neeru', '[Translation in progress] Traditional folk wisdom: "ಪಾಪಿ ಸಮುದ್ರ ಹೊಕ್ಕರು ಮೊಣಕಾಲುದ್ದ ನೀರು". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಪಾಪಿ ಸಮುದ್ರ ಹೊಕ್ಕರು ಮೊಣಕಾಲುದ್ದ ನೀರು". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಪಾಪಿ","ಸಮುದ್ರ","ಹೊಕ್ಕರು","ಮೊಣಕಾಲುದ್ದ","ನೀರು","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ನೂರಾರು ರೋಗಿಗಳನ್ನು ಕೊಂದು ಒಬ್ಬ ವೈದ್ಯ ಆದಂತೆ', 'Nooraaru roogigalannu komdu obba vaidya aadamte', '[Translation in progress] Traditional folk wisdom: "ನೂರಾರು ರೋಗಿಗಳನ್ನು ಕೊಂದು ಒಬ್ಬ ವೈದ್ಯ ಆದಂತೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ನೂರಾರು ರೋಗಿಗಳನ್ನು ಕೊಂದು ಒಬ್ಬ ವೈದ್ಯ ಆದಂತೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ನೂರಾರು","ರೋಗಿಗಳನ್ನು","ಕೊಂದು","ಒಬ್ಬ","ವೈದ್ಯ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಆಸೆಯಿಲ್ಲದವನು ದೇಶಕ್ಕೆ ಶ್ರೀಮಂತ', 'Aaseyilladavanu deeshakke shreemamta', '[Translation in progress] Traditional folk wisdom: "ಆಸೆಯಿಲ್ಲದವನು ದೇಶಕ್ಕೆ ಶ್ರೀಮಂತ". Context: Guidance on money and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಆಸೆಯಿಲ್ಲದವನು ದೇಶಕ್ಕೆ ಶ್ರೀಮಂತ". ಇದು ಹಣಕಾಸು ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'money', 'ಹಣಕಾಸು', 'Used in daily conversations to illustrate money principles and life lessons.', 'ಹಣಕಾಸು ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಆಸೆಯಿಲ್ಲದವನು","ದೇಶಕ್ಕೆ","ಶ್ರೀಮಂತ","ಹಣಕಾಸು"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಕೊಣನಿಗೆ ಕೊಸೆಯೋ ಸಂಕಟ, ಎಮ್ಮೆಗೆ ಈಯೋ ಸಂಕಟ', 'Konanige koseyoo samkata, emmege eeyoo samkata', '[Translation in progress] Traditional folk wisdom: "ಕೊಣನಿಗೆ ಕೊಸೆಯೋ ಸಂಕಟ, ಎಮ್ಮೆಗೆ ಈಯೋ ಸಂಕಟ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಕೊಣನಿಗೆ ಕೊಸೆಯೋ ಸಂಕಟ, ಎಮ್ಮೆಗೆ ಈಯೋ ಸಂಕಟ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಕೊಣನಿಗೆ","ಕೊಸೆಯೋ","ಸಂಕಟ","ಎಮ್ಮೆಗೆ","ಈಯೋ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಜಟ್ಟಿ ಜಾರಿ ಬಿದ್ದರೂ ಮೀಸೆ ಮಣ್ಣಾಗಲಿಲ್ಲ', 'Jatti jaari biddaroo meese mannaagalilla', '[Translation in progress] Traditional folk wisdom: "ಜಟ್ಟಿ ಜಾರಿ ಬಿದ್ದರೂ ಮೀಸೆ ಮಣ್ಣಾಗಲಿಲ್ಲ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಜಟ್ಟಿ ಜಾರಿ ಬಿದ್ದರೂ ಮೀಸೆ ಮಣ್ಣಾಗಲಿಲ್ಲ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಜಟ್ಟಿ","ಜಾರಿ","ಬಿದ್ದರೂ","ಮೀಸೆ","ಮಣ್ಣಾಗಲಿಲ್ಲ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಅತ್ತೆ ಒಡೆದ ಪಾತ್ರೆಗೆ ಬೆಲೆ ಇಲ್ಲ', 'Atte odeda paatrege bele illa', '[Translation in progress] Traditional folk wisdom: "ಅತ್ತೆ ಒಡೆದ ಪಾತ್ರೆಗೆ ಬೆಲೆ ಇಲ್ಲ". Context: Guidance on family and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಅತ್ತೆ ಒಡೆದ ಪಾತ್ರೆಗೆ ಬೆಲೆ ಇಲ್ಲ". ಇದು ಕುಟುಂಬ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'family', 'ಕುಟುಂಬ', 'Used in daily conversations to illustrate family principles and life lessons.', 'ಕುಟುಂಬ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಅತ್ತೆ","ಒಡೆದ","ಪಾತ್ರೆಗೆ","ಬೆಲೆ","ಇಲ್ಲ","ಕುಟುಂಬ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ತಾನು ಮಾಡುವುದು ಉತ್ತಮ; ಮಗ ಮಾಡುವುದು ಮಧ್ಯಮ; ಆಳು ಮಾಡುವುದು ಹಾಳು', 'Taanu maaduvudu uttama; maga maaduvudu madhyama; aalu maaduvudu haalu', '[Translation in progress] Traditional folk wisdom: "ತಾನು ಮಾಡುವುದು ಉತ್ತಮ; ಮಗ ಮಾಡುವುದು ಮಧ್ಯಮ; ಆಳು ಮಾಡುವುದು ಹಾಳು". Context: Guidance on family and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ತಾನು ಮಾಡುವುದು ಉತ್ತಮ; ಮಗ ಮಾಡುವುದು ಮಧ್ಯಮ; ಆಳು ಮಾಡುವುದು ಹಾಳು". ಇದು ಕುಟುಂಬ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'family', 'ಕುಟುಂಬ', 'Used in daily conversations to illustrate family principles and life lessons.', 'ಕುಟುಂಬ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ತಾನು","ಮಾಡುವುದು","ಉತ್ತಮ","ಮಧ್ಯಮ","ಆಳು","ಕುಟುಂಬ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ವಿಧಿ ಕಾಣದ ಎಡೆಗಳಿಲ್ಲ', 'Vidhi kaanada edegalilla', '[Translation in progress] Traditional folk wisdom: "ವಿಧಿ ಕಾಣದ ಎಡೆಗಳಿಲ್ಲ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ವಿಧಿ ಕಾಣದ ಎಡೆಗಳಿಲ್ಲ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ವಿಧಿ","ಕಾಣದ","ಎಡೆಗಳಿಲ್ಲ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಬೀಜದಂತೆ ವೃಕ್ಷ, ವೃಕ್ಷದಂತೆ ಬೀಜ', 'Beejadamte vruksha, vrukshadamte beeja', '[Translation in progress] Traditional folk wisdom: "ಬೀಜದಂತೆ ವೃಕ್ಷ, ವೃಕ್ಷದಂತೆ ಬೀಜ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಬೀಜದಂತೆ ವೃಕ್ಷ, ವೃಕ್ಷದಂತೆ ಬೀಜ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಬೀಜದಂತೆ","ವೃಕ್ಷ","ವೃಕ್ಷದಂತೆ","ಬೀಜ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
    ('ಹಾಗಲಕಾಯಿಗೆ ಬೇವಿನಕಾಯಿ ಸಾಕ್ಷಿ ಹೇಳಿದ ಹಾಗೆ', 'Haagalakaayige beevinakaayi saakshi heelida haage', '[Translation in progress] Traditional folk wisdom: "ಹಾಗಲಕಾಯಿಗೆ ಬೇವಿನಕಾಯಿ ಸಾಕ್ಷಿ ಹೇಳಿದ ಹಾಗೆ". Context: Guidance on life and ethical living.', 'ಸಾಂಪ್ರದಾಯಿಕ ಜನಪದ ಗಾದೆ: "ಹಾಗಲಕಾಯಿಗೆ ಬೇವಿನಕಾಯಿ ಸಾಕ್ಷಿ ಹೇಳಿದ ಹಾಗೆ". ಇದು ಜೀವನ ಹಾಗೂ ಜೀವನಾನುಭವದ ಮೌಲ್ಯವನ್ನು ತಿಳಿಸುತ್ತದೆ.', 'life', 'ಜೀವನ', 'Used in daily conversations to illustrate life principles and life lessons.', 'ಜೀವನ ಹಾಗೂ ದೈನಂದಿನ ಜೀವನದ ಸಂದರ್ಭಗಳಲ್ಲಿ ಹಿರಿಯರು ಬಳಸುವ ನಾಣ್ಣುಡಿ.', '"ಹಾಗಲಕಾಯಿಗೆ","ಬೇವಿನಕಾಯಿ","ಸಾಕ್ಷಿ","ಹೇಳಿದ","ಹಾಗೆ","ಜೀವನ"'::text[], 'ವಿಷಯ ಜನಪ್ರಿಯ ಗಾದೆಗಳು (Vishaya.in)', 0, FALSE),
